FILES = {
    "seed_recovery_v82.py": "\nimport ast\nimport json\nimport os\nimport subprocess\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nREPORT_FILE = Path(\"seed_recovery_report_v82.json\")\nLAST_GREEN_FILE = Path(\"seed_last_green_checkpoint_v82.json\")\nROLLBACK_NOTES = Path(\"seed_recovery_rollback_notes_v82.md\")\n\nCORE_RUNTIME_FILES = [\n    \"seed_cli.py\",\n    \"seed_commands.py\",\n    \"seed_local_chat_v701.py\",\n    \"seed_v85_gate.py\",\n    \"seed_v85_systems.py\",\n    \"seed_self_state_v85.py\",\n    \"seed_recovery_v82.py\",\n    \"seed_runtime_v83.py\",\n    \"seed_privacy_backup_v84.py\",\n    \"seed_release_candidate_v85.py\",\n    \"seed_v81_gate.py\",\n    \"seed_v75_gate.py\",\n    \"seed_v74_gate.py\",\n    \"seed_v731_gate.py\",\n]\n\nSELF_GATE_FORBIDDEN = {\n    \"seed_self_state_v741.py\": \"seed_v75_gate\",\n    \"seed_self_state_v81.py\": \"seed_v81_gate\",\n    \"seed_self_state_v85.py\": \"seed_v85_gate\",\n}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef compile_file(path):\n    try:\n        proc = subprocess.run([sys.executable, \"-m\", \"py_compile\", str(path)], capture_output=True, text=True, timeout=20)\n        return {\"file\": str(path), \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-1200:]}\n    except Exception as e:\n        return {\"file\": str(path), \"ok\": False, \"stderr\": str(e)}\n\ndef compile_all():\n    files = [Path(f) for f in CORE_RUNTIME_FILES if Path(f).exists()]\n    checks = [compile_file(p) for p in files]\n    failed = [c for c in checks if not c[\"ok\"]]\n    return {\"ok\": len(failed) == 0, \"count\": len(checks), \"failed\": failed, \"checks\": checks}\n\ndef file_has_real_gate_import(filename, forbidden_module):\n    p = Path(filename)\n    if not p.exists():\n        return False\n\n    text = p.read_text(errors=\"ignore\")\n    try:\n        tree = ast.parse(text)\n    except Exception:\n        # If parse fails, compile checks will catch it; don't make recursion guard responsible.\n        return False\n\n    for node in ast.walk(tree):\n        # import seed_v85_gate\n        if isinstance(node, ast.Import):\n            for alias in node.names:\n                if alias.name == forbidden_module:\n                    return True\n\n        # from seed_v85_gate import ...\n        if isinstance(node, ast.ImportFrom):\n            if node.module == forbidden_module:\n                return True\n\n        # __import__(\"seed_v85_gate\", ...)\n        if isinstance(node, ast.Call):\n            if isinstance(node.func, ast.Name) and node.func.id == \"__import__\" and node.args:\n                first = node.args[0]\n                if isinstance(first, ast.Constant) and first.value == forbidden_module:\n                    return True\n\n            # gate(\"seed_v85_gate\", \"run_v85_gate\")\n            if isinstance(node.func, ast.Name) and node.func.id in {\"gate\", \"_gate_status\"} and node.args:\n                first = node.args[0]\n                if isinstance(first, ast.Constant) and first.value == forbidden_module:\n                    return True\n\n    return False\n\ndef recursion_guard():\n    warnings = []\n    for filename, forbidden in SELF_GATE_FORBIDDEN.items():\n        if file_has_real_gate_import(filename, forbidden):\n            warnings.append({\n                \"file\": filename,\n                \"forbidden\": forbidden,\n                \"warning\": f\"{filename} should not import/call its own gate module {forbidden}\",\n            })\n    return {\n        \"ok\": len(warnings) == 0,\n        \"warnings\": warnings,\n        \"method\": \"AST-based; ignores comments and harmless strings.\",\n    }\n\ndef dependency_check():\n    import shutil\n    deps = {name: shutil.which(name) for name in [\"ffmpeg\", \"say\", \"aider\", \"git\"]}\n    try:\n        import faster_whisper\n        deps[\"faster_whisper\"] = True\n    except Exception:\n        deps[\"faster_whisper\"] = False\n    return {\"ok\": bool(deps.get(\"git\")), \"deps\": deps}\n\ndef storage_check():\n    try:\n        usage = os.statvfs(\".\")\n        free_gb = usage.f_bavail * usage.f_frsize / (1024**3)\n        total_gb = usage.f_blocks * usage.f_frsize / (1024**3)\n        return {\"ok\": free_gb > 3, \"free_gb\": round(free_gb, 2), \"total_gb\": round(total_gb, 2)}\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e)}\n\ndef mark_last_green(label=\"manual_green_checkpoint\"):\n    data = {\"created_at\": now(), \"version\": \"v85.3.0\", \"label\": label, \"cwd\": str(Path(\".\").resolve())}\n    try:\n        proc = subprocess.run([\"git\", \"rev-parse\", \"--short\", \"HEAD\"], capture_output=True, text=True, timeout=8)\n        if proc.returncode == 0:\n            data[\"git_head\"] = proc.stdout.strip()\n    except Exception:\n        pass\n    LAST_GREEN_FILE.write_text(json.dumps(data, indent=4))\n    return data\n\ndef recovery_summary():\n    comp = compile_all()\n    guard = recursion_guard()\n    deps = dependency_check()\n    storage = storage_check()\n\n    blockers = []\n    warnings = []\n\n    if not comp[\"ok\"]:\n        blockers.append(f\"{len(comp['failed'])} core runtime compile failures\")\n    if not guard[\"ok\"]:\n        blockers.append(\"real recursion guard warning\")\n    if not deps[\"ok\"]:\n        blockers.append(\"missing critical dependency: git\")\n    if not storage[\"ok\"]:\n        warnings.append(\"storage warning\")\n\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v85.3.0\",\n        \"ok\": len(blockers) == 0,\n        \"blockers\": blockers,\n        \"warnings\": warnings,\n        \"compile\": {\"ok\": comp[\"ok\"], \"count\": comp[\"count\"], \"failed\": comp[\"failed\"][:10]},\n        \"recursion_guard\": guard,\n        \"dependencies\": deps,\n        \"storage\": storage,\n        \"last_green\": json.loads(LAST_GREEN_FILE.read_text()) if LAST_GREEN_FILE.exists() else None,\n        \"note\": \"v85.3 uses AST recursion guard, so comments mentioning seed_v75_gate/seed_v85_gate no longer create false blockers.\",\n    }\n    REPORT_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef write_rollback_notes():\n    s = recovery_summary()\n    ROLLBACK_NOTES.write_text(\"\\n\".join([\n        \"# Seed v85.3 Recovery Notes\",\n        \"\",\n        f\"Created: {now()}\",\n        f\"OK: {s.get('ok')}\",\n        f\"Blockers: {s.get('blockers')}\",\n        f\"Warnings: {s.get('warnings')}\",\n        \"\",\n        \"Rollback:\",\n        \"1. Stop Seed servers with Ctrl+C.\",\n        \"2. Restore latest seed_backup_*_green folder.\",\n        \"3. Or use git reset --hard <green_commit>.\",\n        \"4. Re-run seed_v85_gate.py.\",\n    ]))\n    return {\"ok\": True, \"file\": str(ROLLBACK_NOTES)}\n\ndef show_recovery():\n    d = recovery_summary()\n    print(\"\\n=== SEED v85.3 RECOVERY ===\")\n    print(f\"OK: {d['ok']}\")\n    print(f\"Blockers: {d['blockers']}\")\n    print(f\"Warnings: {d['warnings']}\")\n    print(f\"Compile: {d['compile']['ok']} ({d['compile']['count']} core runtime files)\")\n    print(f\"Recursion guard: {d['recursion_guard']}\")\n    print(f\"Deps: {d['dependencies']['deps']}\")\n\nif __name__ == \"__main__\":\n    show_recovery()\n",
    "seed_v85_gate.py": "\nimport json\nimport subprocess\nimport sys\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\n\nREPORT_FILE = Path(\"seed_v85_gate_report.json\")\n\nCORE_MODULES = [\n    \"seed_self_state_v85.py\",\n    \"seed_recovery_v82.py\",\n    \"seed_runtime_v83.py\",\n    \"seed_privacy_backup_v84.py\",\n    \"seed_release_candidate_v85.py\",\n    \"seed_v85_systems.py\",\n    \"seed_v85_gate.py\",\n    \"seed_v85_commands.py\",\n    \"seed_natural_intent_router_v85.py\",\n    \"seed_v81_gate.py\",\n    \"seed_v75_gate.py\",\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef compile_module(module):\n    if not Path(module).exists():\n        return {\"module\": module, \"ok\": False, \"stderr\": \"missing\"}\n    proc = subprocess.run([sys.executable, \"-m\", \"py_compile\", module], capture_output=True, text=True, timeout=20)\n    return {\"module\": module, \"ok\": proc.returncode == 0, \"stderr\": proc.stderr[-1200:]}\n\ndef read_report(path):\n    p = Path(path)\n    if not p.exists():\n        return {}\n    try:\n        return json.loads(p.read_text(errors=\"ignore\"))\n    except Exception:\n        return {}\n\ndef report_ready(path, max_age_seconds=86400):\n    p = Path(path)\n    if not p.exists():\n        return False, {\"source\": \"missing_report\", \"path\": str(p)}\n    data = read_report(path)\n    age = time.time() - p.stat().st_mtime\n    return data.get(\"ready\") is True and age <= max_age_seconds, {\n        \"source\": \"cached_report\",\n        \"path\": str(p),\n        \"age_seconds\": round(age, 1),\n        \"ready\": data.get(\"ready\"),\n        \"version\": data.get(\"version\"),\n    }\n\ndef run_v85_gate(deep=False):\n    checks = [compile_module(m) for m in CORE_MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n\n    v81_ok, v81_meta = report_ready(\"seed_v81_gate_report.json\")\n    v75_ok, v75_meta = report_ready(\"seed_v75_gate_report.json\")\n\n    if deep:\n        for script, key in [(\"seed_v81_gate.py\", \"v81\"), (\"seed_v75_gate.py\", \"v75\")]:\n            try:\n                proc = subprocess.run([sys.executable, script], capture_output=True, text=True, timeout=240)\n                meta = {\"source\": \"deep_subprocess\", \"returncode\": proc.returncode, \"stdout_tail\": proc.stdout[-2000:], \"stderr_tail\": proc.stderr[-2000:]}\n                if key == \"v81\":\n                    v81_ok, v81_meta = proc.returncode == 0, meta\n                else:\n                    v75_ok, v75_meta = proc.returncode == 0, meta\n            except Exception as e:\n                if key == \"v81\":\n                    v81_ok, v81_meta = False, {\"source\": \"deep_subprocess\", \"error\": str(e)}\n                else:\n                    v75_ok, v75_meta = False, {\"source\": \"deep_subprocess\", \"error\": str(e)}\n\n    try:\n        from seed_self_state_v85 import build_self_state\n        s = build_self_state()\n        truth_ok = s.get(\"true_current_version\") in {\"v85.0.0\", \"v85.1.0\", \"v85.2.0\", \"v85.3.0\"}\n        truth_meta = {\"current\": s.get(\"true_current_version\"), \"green_layers\": s.get(\"installed_layers_green\", [])}\n    except Exception as e:\n        truth_ok, truth_meta = False, {\"error\": str(e)}\n\n    try:\n        from seed_runtime_v83 import install_seed_script\n        script = install_seed_script()\n        script_ok = script.get(\"ok\") is True and Path(\"seed\").exists()\n    except Exception as e:\n        script, script_ok = {\"ok\": False, \"error\": str(e)}, False\n\n    try:\n        from seed_recovery_v82 import recovery_summary\n        rec = recovery_summary()\n        recovery_ok = rec.get(\"ok\") is True\n    except Exception as e:\n        rec, recovery_ok = {\"ok\": False, \"error\": str(e)}, False\n\n    report = {\n        \"created_at\": now(),\n        \"version\": \"v85.3.0\",\n        \"ready\": modules_ok and v81_ok and v75_ok and truth_ok and script_ok and recovery_ok,\n        \"modules_ok\": modules_ok,\n        \"v81_ok\": v81_ok,\n        \"v75_ok\": v75_ok,\n        \"truth_ok\": truth_ok,\n        \"script_ok\": script_ok,\n        \"recovery_ok\": recovery_ok,\n        \"module_checks\": checks,\n        \"details\": {\n            \"v81\": v81_meta,\n            \"v75\": v75_meta,\n            \"truth\": truth_meta,\n            \"runtime_script\": script,\n            \"recovery\": {\"ok\": rec.get(\"ok\"), \"blockers\": rec.get(\"blockers\"), \"warnings\": rec.get(\"warnings\"), \"recursion_guard\": rec.get(\"recursion_guard\")},\n            \"mode\": \"deep\" if deep else \"fast_cached\",\n        },\n        \"note\": \"v85.3 fast gate with AST recursion guard.\",\n    }\n    REPORT_FILE.write_text(json.dumps(report, indent=4, ensure_ascii=False))\n    return report\n\ndef show_v85_gate(deep=False):\n    r = run_v85_gate(deep=deep)\n    print(\"\\n=== SEED v85.3 FAST REAL V1 PREP GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"v81 OK: {r['v81_ok']}\")\n    print(f\"v75 OK: {r['v75_ok']}\")\n    print(f\"Truth OK: {r['truth_ok']}\")\n    print(f\"Script OK: {r['script_ok']}\")\n    print(f\"Recovery OK: {r['recovery_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v85_gate(deep=\"--deep\" in sys.argv)\n",
    "seed_v85_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_v85_systems_state.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\n\ndef build_v85_state():\n    cards = [\n        safe(\"v82 Recovery\", \"AST recursion guard, fast core runtime checks, rollback notes.\", lambda: __import__(\"seed_recovery_v82\", fromlist=[\"recovery_summary\"]).recovery_summary()),\n        safe(\"v83 One-Command Runtime\", \"Seed can start via ./seed or seed_start.sh.\", lambda: __import__(\"seed_runtime_v83\", fromlist=[\"runtime_status\"]).runtime_status()),\n        safe(\"v84 Backup/Privacy\", \"Backup, export memory, forget by keyword.\", lambda: __import__(\"seed_privacy_backup_v84\", fromlist=[\"privacy_status\"]).privacy_status()),\n        safe(\"v85 Release Candidate\", \"RC report and README generation.\", lambda: __import__(\"seed_release_candidate_v85\", fromlist=[\"release_candidate_summary\"]).release_candidate_summary()),\n        safe(\"Self-State Truth\", \"Current version override is v85.x.\", lambda: __import__(\"seed_self_state_v85\", fromlist=[\"build_self_state\"]).build_self_state()),\n    ]\n    data = {\"created_at\": now(), \"version\": \"v85.3.0\", \"ok\": all(c[\"status\"] != \"error\" for c in cards), \"cards\": cards}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_v85_status():\n    data = build_v85_state()\n    print(\"\\n=== SEED v85.3 FAST REAL V1 PREP STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for c in data[\"cards\"]:\n        print(f\"- {c['title']}: {c['status']} \u2014 {c['summary']}\")\n\nif __name__ == \"__main__\":\n    show_v85_status()\n",
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v85.3.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v85.3.0"', text, flags=re.M)
if "SEED_V853_AST_RECOVERY_GUARD" not in text:
    text += '\nSEED_V853_AST_RECOVERY_GUARD = True\n'
p.write_text(text)
print("Updated seed_config.py")

p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v85.3 — AST Recovery Guard Hotfix" not in text:
    text += """
## Seed v85.3 — AST Recovery Guard Hotfix

Fixes false recursion warning in recovery:
- Old guard matched comments/strings containing seed_v75_gate or seed_v85_gate.
- New guard uses Python AST and only flags real imports/calls.
- v85 fast gate remains cached and quick.
"""
p.write_text(text)
print("Updated Seed_Core.md")

for m in ["seed_recovery_v82.py", "seed_v85_gate.py", "seed_v85_systems.py", "seed_commands.py"]:
    if Path(m).exists():
        proc = subprocess.run([sys.executable, "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
        print("$ python -m py_compile", m)
        if proc.returncode == 0:
            print("OK")
        else:
            print(proc.stderr)
            sys.exit(proc.returncode)

print("\nSeed v85.3 AST recovery guard hotfix installed.")
